package com.hospital.smartqueue.doctor.scheduling.api;
import com.hospital.smartqueue.doctor.scheduling.application.DoctorScheduleService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.time.*; import java.util.*;
@RestController @RequestMapping("/api/v1/hospitals/{hospitalId}/branches/{branchId}/doctors/{doctorId}") public class DoctorScheduleController {private final DoctorScheduleService service; private final com.hospital.smartqueue.doctor.scheduling.application.DoctorLeaveService leaves; private final com.hospital.smartqueue.doctor.scheduling.application.ScheduleExceptionService exceptions; public DoctorScheduleController(DoctorScheduleService s,com.hospital.smartqueue.doctor.scheduling.application.DoctorLeaveService l,com.hospital.smartqueue.doctor.scheduling.application.ScheduleExceptionService e){service=s;leaves=l;exceptions=e;} @PutMapping("/schedule") public ScheduleResponse save(@PathVariable UUID hospitalId,@PathVariable UUID branchId,@PathVariable UUID doctorId,@Valid @RequestBody ScheduleRequest request){return ScheduleResponse.from(service.save(hospitalId,branchId,doctorId,request));} @GetMapping("/schedule") public ScheduleResponse get(@PathVariable UUID hospitalId,@PathVariable UUID branchId,@PathVariable UUID doctorId,@RequestParam LocalDate onDate){return ScheduleResponse.from(service.get(hospitalId,branchId,doctorId,onDate));} @PostMapping("/leave") @ResponseStatus(HttpStatus.CREATED) public Map<String,UUID> leave(@PathVariable UUID hospitalId,@PathVariable UUID branchId,@PathVariable UUID doctorId,@Valid @RequestBody LeaveRequest request){return Map.of("id",leaves.add(hospitalId,branchId,doctorId,request));} @PostMapping("/exceptions") @ResponseStatus(HttpStatus.CREATED) public ScheduleExceptionResponse createException(@PathVariable UUID hospitalId,@PathVariable UUID branchId,@PathVariable UUID doctorId,@Valid @RequestBody ScheduleExceptionRequest r){return ScheduleExceptionResponse.from(exceptions.create(hospitalId,branchId,doctorId,r));} @GetMapping("/exceptions/{id}") public ScheduleExceptionResponse getException(@PathVariable UUID hospitalId,@PathVariable UUID branchId,@PathVariable UUID doctorId,@PathVariable UUID id){return ScheduleExceptionResponse.from(exceptions.get(hospitalId,branchId,doctorId,id));} @PutMapping("/exceptions/{id}") public ScheduleExceptionResponse updateException(@PathVariable UUID hospitalId,@PathVariable UUID branchId,@PathVariable UUID doctorId,@PathVariable UUID id,@Valid @RequestBody ScheduleExceptionRequest r){return ScheduleExceptionResponse.from(exceptions.update(hospitalId,branchId,doctorId,id,r));} @DeleteMapping("/exceptions/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void deleteException(@PathVariable UUID hospitalId,@PathVariable UUID branchId,@PathVariable UUID doctorId,@PathVariable UUID id,@RequestParam long expectedVersion){exceptions.delete(hospitalId,branchId,doctorId,id,expectedVersion);}}
